-- public.vehicle_near(p_world uuid, p_x double precision, p_y double precision, p_range double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.vehicle_near(p_world uuid, p_x double precision, p_y double precision, p_range double precision DEFAULT 5)
 RETURNS placed
 LANGUAGE sql
 STABLE
AS $function$
  select p.* from placed p
  join vehicle_def v on v.id = p.sub
  where p.world_id = p_world and p.kind = 'furniture'
    and team_size(p_world, p.id) < v.yokes
    and sqrt((p.cx - p_x) ^ 2 + (p.cy - p_y) ^ 2) <= p_range
  order by sqrt((p.cx - p_x) ^ 2 + (p.cy - p_y) ^ 2)
  limit 1
$function$
